from pathlib import Path
import sys
p=Path(sys.argv[1])
s=p.read_text()

def repl(old,new,label,required=True):
    global s
    if old in s:
        s=s.replace(old,new)
        print('patched',label)
    elif required:
        raise SystemExit(f'missing expected block: {label}')

repl('''        fills = [LIGHT_GRAY, WHITE, LIGHT_GRAY]\n        rects = VGroup()\n        x = x0\n        centers = []\n        for w, fill in zip(widths, fills):\n            r = Rectangle(width=w, height=h, stroke_color=BLACK_LINE, stroke_width=3.4,\n                          fill_color=fill, fill_opacity=0.68 if fill != WHITE else 1.0)\n''','''        fill_specs = [(LIGHT_GRAY, 0.68), (WHITE, 1.0), (LIGHT_GRAY, 0.68)]\n        rects = VGroup()\n        x = x0\n        centers = []\n        for w, (fill, opacity) in zip(widths, fill_specs):\n            r = Rectangle(width=w, height=h, stroke_color=BLACK_LINE, stroke_width=3.4,\n                          fill_color=fill, fill_opacity=opacity)\n''','color opacity',required=False)

s=s.replace('class Geometry8Week3ShadedAreasSeniorV1(JPMathClassroomScene):','class Geometry8Week3ShadedAreasSeniorV2(JPMathClassroomScene):')

repl('''        self.play(FadeIn(outer), FadeIn(outer_b), FadeIn(outer_l), run_time=RUN_NORMAL)\n        whole_text = self.step_card("1", "WHOLE AREA", ["Outer square", "side = 10 cm"], width=5.85)\n        whole_text.move_to(RIGHT * 3.45 + UP * 1.45)\n        self.play(FadeIn(whole_text), run_time=RUN_NORMAL)\n        whole_eq = self.math(r"A_{\\text{whole}}=10^2=100\\,\\mathrm{cm}^2", 57)\n        whole_eq.move_to(RIGHT * 3.45 + UP * 0.05)\n        self.play(TransformFromCopy(outer_b[1], whole_eq), run_time=RUN_SLOW)\n        self.wait(PAUSE_EXPLAIN)\n\n        self.play(FadeIn(inner), FadeIn(inner_b), run_time=RUN_NORMAL)\n        missing = self.step_card("2", "MISSING AREA", ["Inner square", "side = 4 cm"], width=5.85)\n        missing.move_to(RIGHT * 3.45 + DOWN * 1.20)\n        self.play(ReplacementTransform(whole_text, missing), run_time=RUN_NORMAL)\n        missing_eq = self.math(r"A_{\\text{missing}}=4^2=16\\,\\mathrm{cm}^2", 55)\n        missing_eq.move_to(RIGHT * 3.45 + DOWN * 2.45)\n        self.play(TransformFromCopy(inner_b[1], missing_eq), run_time=RUN_SLOW)\n        self.wait(PAUSE_EXPLAIN)\n\n        result = self.math(r"\\boxed{A_{\\text{shaded}}=100-16=84\\,\\mathrm{cm}^2}", 61)\n        result.move_to(RIGHT * 3.45 + DOWN * 0.10)\n        self.play(FadeOut(missing), FadeOut(whole_eq), FadeOut(missing_eq), run_time=RUN_QUICK)\n        self.play(FadeIn(result, shift=UP * 0.10), inner.animate.set_fill(WHITE, opacity=1.0), run_time=RUN_NORMAL)\n''','''        self.play(FadeIn(outer), FadeIn(outer_b), FadeIn(outer_l), run_time=RUN_NORMAL)\n        whole_text = self.step_card("1", "WHOLE AREA", ["Outer square", "side = 10 cm"], width=5.85)\n        whole_text.move_to(RIGHT * 3.45 + UP * 1.55)\n        self.play(FadeIn(whole_text), run_time=RUN_NORMAL)\n        whole_eq = self.math(r"A_{\\text{whole}}=10^2=100\\,\\mathrm{cm}^2", 54)\n        whole_eq.move_to(RIGHT * 3.45 + DOWN * 0.35)\n        self.play(TransformFromCopy(outer_b[1], whole_eq), run_time=RUN_SLOW)\n        self.wait(PAUSE_EXPLAIN)\n\n        self.play(FadeIn(inner), FadeIn(inner_b), run_time=RUN_NORMAL)\n        missing = self.step_card("2", "MISSING AREA", ["Inner square", "side = 4 cm"], width=5.85)\n        missing.move_to(RIGHT * 3.45 + UP * 1.55)\n        missing_eq = self.math(r"A_{\\text{missing}}=4^2=16\\,\\mathrm{cm}^2", 54)\n        missing_eq.move_to(RIGHT * 3.45 + DOWN * 0.35)\n        self.play(ReplacementTransform(whole_text, missing), ReplacementTransform(whole_eq, missing_eq), run_time=RUN_NORMAL)\n        self.play(Indicate(inner, scale_factor=1.04), run_time=RUN_NORMAL)\n        self.wait(PAUSE_EXPLAIN)\n\n        result = self.math(r"\\boxed{A_{\\text{shaded}}=100-16=84\\,\\mathrm{cm}^2}", 58)\n        result.move_to(RIGHT * 3.45 + DOWN * 0.35)\n        self.play(FadeOut(missing), ReplacementTransform(missing_eq, result), run_time=RUN_NORMAL)\n        self.play(Indicate(outer, scale_factor=1.015), inner.animate.set_fill(WHITE, opacity=1.0), run_time=RUN_NORMAL)\n''','square example layout')

repl('''        method1 = self.text("METHOD 1 — ADD SHADED PIECES", 38, BOLD).move_to(RIGHT * 3.70 + UP * 1.80)\n''','''        method1 = self.text("METHOD 1 — ADD SHADED REGIONS", 34, BOLD)\n        self.fit(method1, 6.15, 0.62)\n        method1.move_to(RIGHT * 3.75 + UP * 1.65)\n''','method 1 title')
